import itertools
# demos: (bh, bw, ch, cw, gap, grow)
D=[(8,7,4,3,2,2),(5,5,1,1,2,1),(4,4,2,2,1,2),(7,7,3,3,2,3),(3,3,1,1,1,1)]
T=(6,6,4,4,1)
feats=lambda b: dict(bh=b[0],bw=b[1],ch=b[2],cw=b[3],gap=b[4],
    bmin=min(b[0],b[1]),bmax=max(b[0],b[1]),cmin=min(b[2],b[3]),cmax=max(b[2],b[3]),
    area=b[0]*b[1],carea=b[2]*b[3])
names=['bh','bw','ch','cw','gap','bmin','bmax','cmin','cmax','area','carea']
sols=[]
for n in (1,2,3):
    for combo in itertools.combinations(range(len(names)),n):
        for coefs in itertools.product([-2,-1,1,2],repeat=n):
            for const in range(-3,4):
                ok=True
                for d in D:
                    f=feats(d); v=const+sum(c*f[names[i]] for c,i in zip(coefs,combo))
                    if v!=d[5]: ok=False;break
                if ok:
                    ft=feats(T); vt=const+sum(c*ft[names[i]] for c,i in zip(coefs,combo))
                    sols.append(([names[i] for i in combo],coefs,const,vt))
for s in sols: print(s)
print(len(sols))

import itertools
# clean demos: (core, gap) -> box (block + 2*grow); D1 excluded (grid-capped)
pts=[(1,1,5),(1,2,7),(2,1,8),(3,2,13)]
# box = a*c^2+b*c*g+e*g^2+d*c+f*g+h, coeffs in [-5..5]
terms=lambda c,g,a,b,e,d,f,h: a*c*c+b*c*g+e*g*g+d*c+f*g+h
sols=[]
rng=range(-4,6)
for a,b,e,d,f,h in itertools.product(rng,repeat=6):
    if all(terms(c,g,a,b,e,d,f,h)==B for c,g,B in pts):
        for cT,gT in [(4,1)]:
            BT=terms(cT,gT,a,b,e,d,f,h)
            grow=(BT-6)/2
            if 0<grow<=7 and BT%2==0:
                sols.append(((a,b,e,d,f,h),BT,grow))
for s in sols: print(s)
print(len(sols))

